    # Propagate DOWN from each non-zero
    for start_r in sorted(original_nonzero):
        val = col_vals[start_r]
        changes = []
        for r in range(start_r + 1, 16):
            if r not in original_nonzero and col_vals[r] == 0:
                col_vals[r] = val
                changes.append(r)
            else:
                break
